扫描命中行的代码上下文（±25 行窗口，L<n> 为包内原始行号）：
L1: import { execFile } from "node:child_process";
L2: import { existsSync } from "node:fs";
L3: function findPullRequest(directory, env) {
L4:     return new Promise((resolve, reject) => {
L5:         execFile("gh", ["pr", "view", "--json", "url", "--jq", ".url"], { cwd: directory, env, timeout: 15_000 }, (error, stdout, stderr) => {
L6:             if (error)
L7:                 return reject(Object.assign(error, { stderr }));
L8:             resolve(stdout.trim());
L9:         });
L10:     });
L11: }
L12: function describe(error, directory) {
L13:     if (error.code === "ENOENT") {
L14:         return { variant: "error", title: "GitHub CLI not found", message: "Install gh to open pull requests." };
L15:     }
L16:     const stderr = error.stderr ?? "";
L17:     const branch = stderr.match(/no pull requests found for branch "(.+)"/)?.[1];
L18:     if (branch)
L19:         return { variant: "warning", title: "No pull request", message: `Branch ${branch} has no pull request.` };
L20:     if (/not a git repository/i.test(stderr)) {
L21:         return { variant: "warning", title: "Not a Git repository", message: directory };
L22:     }
L23:     if (/not on any branch/i.test(stderr)) {
L24:         return { variant: "warning", title: "No branch checked out", message: "Check out a branch to open its pull request." };
L25:     }
L26:     if (stderr.includes("gh auth login")) {
L27:         return { variant: "error", title: "GitHub CLI not signed in", message: "Run gh auth login to open pull requests." };
L28:     }
L29:     const line = stderr.split("\n").map((line) => line.trim()).find(Boolean);
L30:     return { variant: "error", title: "Could not open pull request", message: line || error.message };

